"""Exact one-buffer isolation and original sink preservation certificate."""
import copy,re
from decimal import Decimal
from common import *
from route_audit import incidence,same_wiring
from structure import signature_graph,groups,attr
from receive_physical import block

def audit_cap(stage,previous,before,after,lib):
 sm=artifacts(stage);plan=load(stage/'plan.json');need(plan['stage_manifest_sha256']==sha(previous/'manifest.json')and sm['plan_sha256']==sha(stage/'plan.json')and type(sm['buffer_count'])is int and type(plan['buffer_count'])is int and sm['buffer_count']==plan['buffer_count'],'frozen exact plan')
 canon=signature_graph(before,lib);clock=canon(before['ports']['clk']['bits'][0])[0];need(type(plan['target'])is int and plan['target']in(93,97)and plan['library_sha256']==sha(LIB)and plan['status']in('FROZEN_ACTUAL_RESIDUAL_CAP_CANDIDATE_NOT_EXECUTED','FROZEN_ACTUAL_MARGIN80_BATCH_NOT_EXECUTED'),'exact typed target and library plan');oldrefs,old_dirs,oldmeta=incidence(before);newrefs,new_dirs,newmeta=incidence(after);need(len(plan['plan'])==plan['buffer_count']and len({q['driver_pin']for q in plan['plan']})==plan['buffer_count'],'unique complete plan rows');actual_new=set(after['cells'])-set(before['cells']);actual_names={}
 for q in plan['plan']:
  matches=[n for n in actual_new if re.fullmatch(re.escape(q['new_buffer_name'])+r'\d+',n)];need(len(matches)==1,'one actual auto-numbered instance per requested base name');actual_names[q['new_buffer_name']]=matches[0]
 names=set(actual_names.values());need(not names&set(before['cells'])and len({q['new_net_name']for q in plan['plan']})==len(plan['plan'])and not {q['new_net_name']for q in plan['plan']}&set(before['netnames']),'new instance and net names collision-free');need(len(names)==plan['buffer_count']and 0<len(names)<=(502 if plan.get('candidate')==4 else 64) and set(after['cells'])-set(before['cells'])==names and set(before['cells'])<=set(after['cells']),'exact added buffer set, no deleted cells')
 for n in before['cells']:need(oldmeta[n]==newmeta[n],'no resize/function/parameter/width change to any prior cell')
 if plan.get('candidate')==4:
  need(plan['contract_sha256']==sha(HERE/'margin_contract.json'),'same full batch contract');frozen=load(HERE/'margin_contract.json')['targets'][str(plan['target'])];need(plan['stage_manifest_sha256']==frozen['stage_manifest_sha256'],'fixed batch source');d=Path(plan['distribution_directory']);artifacts(d);need(sha(d/'distribution.json')==plan['distribution_sha256']==frozen['distribution_sha256'],'frozen full cap source');selected=sorted([x['pin']for x in load(d/'distribution.json')['records']if Decimal(x['ratio'])>=Decimal('.80')]);need(selected==[x['pin']for x in frozen['drivers']]==sorted(q['driver_pin']for q in plan['plan']),'all and only .80 batch');need({q['driver_pin']:q['new_cell']for q in plan['plan']}=={q['pin']:q['cell']for q in frozen['drivers']},'frozen X4/X8 assignment');need(sha(Path(sm['plan_directory'])/'plan.json')==sm['plan_sha256'],'original executed plan payload');body=dict(groups(LIB.read_text(),'cell'))
  for q in plan['plan']:
   n,pn=q['driver_pin'].rsplit('/',1);master=before['cells'][n]['type'];oldlim=Decimal(attr(dict(groups(body[master],'pin'))[pn],'max_capacitance'));newlim=Decimal(attr(dict(groups(body[q['new_cell']],'pin'))['Z'],'max_capacitance'));incap=max(lib[q['new_cell']]['pins']['A']['cap'].values());need(incap<=Decimal('.8')*oldlim and Decimal(q['observed_cap_fF'])<=Decimal('.8')*newlim,'independent actual Liberty input and observed output margin');need(incap==Decimal(q['new_input_cap_fF'])and oldlim==Decimal(q['old_limit_fF'])and newlim==Decimal(q['new_limit_fF']),'exact priced library quantities')
  previous_def=(previous/'placed.def').read_text();expected_wires=len(re.findall(r'\+ ROUTED ',previous_def));clear=block((stage/'flow.log').read_text(),'BEGIN_OLD_ROUTE_CLEAR','END_OLD_ROUTE_CLEAR');need(clear.strip()=='CLEARED_OLD_REGULAR_WIRES='+str(expected_wires),'only prior actual regular routing geometry cleared, counted independently')
 elif plan.get('candidate')==5:
  need(type(plan['candidate'])is int and plan['target']==93 and sha(previous/'manifest.json')=='c99f0fbfe94de9f6153791148ea00451caae682337938d0baeba715393c2cc87' and sorted(q['driver_pin']for q in plan['plan'])==['_38466_/Z','_38550_/Z','_72214_/Q','_72242_/Q'] and len(names)==4,'sole frozen four-driver93 joint plan');receipt=Path(plan['receipt_directory'])/'receipt.json';need(sha(receipt)==plan['receipt_sha256'],'original strict receipt binding');rr=load(receipt)['result'];need(rr['stage_manifest_sha256']==sha(previous/'manifest.json'),'source strict stage binding');bad={x['pin']:x for x in rr['strict_electrical']['scenarios'][0]['checks']['max_capacitance']['strict_exceedances']};need(set(bad)=={q['driver_pin']for q in plan['plan']},'all and only strict cap violations');body=dict(groups(LIB.read_text(),'cell'))
  for q in plan['plan']:
   need(q['new_cell']=='BUF_X4','joint candidate permits only frozen BUF_X4');n,pn=q['driver_pin'].rsplit('/',1);oldlim=Decimal(attr(dict(groups(body[before['cells'][n]['type']],'pin'))[pn],'max_capacitance'));newlim=Decimal(attr(dict(groups(body['BUF_X4'],'pin'))['Z'],'max_capacitance'));need(max(lib['BUF_X4']['pins']['A']['cap'].values())<=Decimal('.8')*oldlim and Decimal(q['observed_cap_fF'])<=Decimal('.8')*newlim and q['observed_cap_fF']==bad[q['driver_pin']]['actual'],'independent precise library input and original full cap load')
 elif plan.get('candidate')==6:
  need(type(plan['candidate'])is int and plan['target']==97 and sha(previous/'manifest.json')=='419c8194d84a9b8d272dd41d6461ae241e8f2b8212b3f14c311a4df7b3d6b9db' and sorted(q['driver_pin']for q in plan['plan'])==['_73496_/ZN'] and len(names)==1,'sole frozen one-driver97 joint plan');receipt=Path(plan['receipt_directory'])/'receipt.json';need(sha(receipt)==plan['receipt_sha256'],'original strict receipt binding');rr=load(receipt)['result'];need(rr['stage_manifest_sha256']==plan['evidence_stage_manifest_sha256']=='e91f8d13c81a189f56ebbdfaa28c13a29f21304354929706d0e07cb45469e271' and sha(Path(plan['evidence_stage_directory'])/'manifest.json')==plan['evidence_stage_manifest_sha256'] and sha(Path(plan['evidence_stage_directory'])/'final.v')==sha(previous/'final.v'),'source strict stage binding');bad={x['pin']:x for x in rr['strict_electrical']['scenarios'][0]['checks']['max_capacitance']['strict_exceedances']};need(set(bad)=={q['driver_pin']for q in plan['plan']},'all and only strict cap violations');body=dict(groups(LIB.read_text(),'cell'))
  for q in plan['plan']:
   need(q['new_cell']=='BUF_X4','joint candidate permits only frozen BUF_X4');n,pn=q['driver_pin'].rsplit('/',1);oldlim=Decimal(attr(dict(groups(body[before['cells'][n]['type']],'pin'))[pn],'max_capacitance'));newlim=Decimal(attr(dict(groups(body['BUF_X4'],'pin'))['Z'],'max_capacitance'));need(max(lib['BUF_X4']['pins']['A']['cap'].values())<=Decimal('.8')*oldlim and Decimal(q['observed_cap_fF'])<=Decimal('.8')*newlim and q['observed_cap_fF']==bad[q['driver_pin']]['actual'],'independent precise library input and original full cap load')
 else:
  log=(previous/'flow.log').read_text();part=block(block(log,'BEGIN_SCENARIO_10','END_SCENARIO_10'),'BEGIN_ELECTRICAL_REPORT','END_ELECTRICAL_REPORT').split('max capacitance',1)[1];drivers=set(re.findall(r'(?m)^(\S+)\s+[0-9.]+\s+[0-9.]+\s+-[0-9.]+\s+\(VIOLATED\)',part));need(drivers=={q['driver_pin']for q in plan['plan']},'all and only actual previous cap violations')

 virtual=copy.deepcopy(after);aliases={};proof=[]
 for q in plan['plan']:
  n,p=q['driver_pin'].rsplit('/',1);bn=actual_names[q['new_buffer_name']];buf=after['cells'][bn];need(buf['type']==q['new_cell']and buf['type']in('BUF_X4','BUF_X8')and lib[buf['type']]['transparent']==('wire','A','Z',0)and set(buf['connections'])=={'A','Z'},'fixed transparent buffer');a=buf['connections']['A'][0];z=buf['connections']['Z'][0];oldbit=before['cells'][n]['connections'][p][0];need(canon(oldbit)[0]!=clock,'no clock buffer candidate');dbit=after['cells'][n]['connections'][p][0];ref=n+':'+p;need(dbit==a and a!=z and newrefs[a]=={ref,bn+':A'},'old driver now drives only buffer input');need(newrefs[z]==oldrefs[oldbit]-{ref}|{bn+':Z'},'buffer output carries all and only original sinks');aliases[z]=a;del virtual['cells'][bn];proof.append({'driver_pin':q['driver_pin'],'requested_buffer_base_name':q['new_buffer_name'],'buffer':bn,'original_sink_count':len(oldrefs[oldbit])-1,'new_driver_sink_count':1,'new_buffer_sink_count':len(newrefs[z])-1})
 for c in virtual['cells'].values():
  for p,bs in c['connections'].items():c['connections'][p]=[aliases.get(b,b)for b in bs]
 for p in virtual['ports'].values():p['bits']=[aliases.get(b,b)for b in p['bits']]
 identity=same_wiring(before,virtual);area=sum((lib[after['cells'][n]['type']]['area']for n in names),Decimal(0));need(area==Decimal(plan['total_added_cell_area_um2']),'exact explicit inventory area')
 return {'status':'PASS_EACH_OLD_DRIVER_ISOLATED_ALL_OLD_SINKS_PRESERVED_AND_NO_OTHER_CHANGE','buffers':proof,'new_histogram':{master:sum(after['cells'][n]['type']==master for n in names)for master in sorted({after['cells'][n]['type']for n in names})},'explicit_added_area_um2':str(area),'collapsed_electrical_identity':identity}
